const STATUS = { answering: { es: 'Respondiendo tu consulta', en: 'Answering your question' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.answering[lang] } }];

const data = $('Status Text: Answering').first().json;
const { language, message, error, intention_nodes, extracted_files } = data;

const nodes = intention_nodes || {};
const activeNode = nodes[data.active_node_id] || null;
const nodeList = Object.values(nodes);

// Selected vs. not is the ONLY thing that decides scope here: a node selected
// (active_node_id set) means the question is about THAT node specifically -- its own
// state, status, and error, nothing else, no guessing across other nodes. No node
// selected means the question is about the broader chat/intention history instead --
// never inferred by scanning intention_nodes for "the last failed one" or similar
// heuristics, which previously hid the right node's error_detail whenever it wasn't
// simply the most recent failure.
const contextBlock = {
  selected_intention_node: activeNode ? {
    id: activeNode.id,
    process_id: activeNode.process_id,
    name: activeNode.process_definition?.name || null,
    status: activeNode.status,
    form_state: activeNode.form_state || null,
    error_detail: activeNode.error_detail || null,
  } : null,
  historical_intention_nodes: activeNode ? null : nodeList.map((n) => ({
    id: n.id,
    process_id: n.process_id,
    name: n.process_definition?.name || null,
    status: n.status,
    error_detail: n.error_detail || null,
  })),
  current_turn_error: error || null,
  attached_files: (extracted_files || []).map((f) => ({
    bucket_file_id: f.bucket_file_id,
    content_preview: (f.extracted_content || '').slice(0, 2000),
    error: f.error,
  })),
};

const chatInput = `Respond in: ${language}.

CURRENT STATE (for grounding your answer, not to repeat verbatim):
\`\`\`json
${JSON.stringify(contextBlock, null, 2)}
\`\`\`

USER MESSAGE:
${message}`;
return [{ json: { ...data, chatInput } }];

// error-parser.json's non-error branch hands back _parsed (the raw agent output, JSON-
// parsed) instead of the message field this file used to extract inline in its own
// Recover State node -- lift it out here, same fallback order as before: the parsed
// object's own message field, or the raw output text if parsing failed.
return [{ json: { ...$json, message: ($json._parsed && $json._parsed.message) || $json.output || '' } }];
